value, err := rand.Int(rand.Reader, big.NewInt(100))
if err != nil {
	panic(err)
}
const message = "Hello {{.Greeting}}: {{.Number}}"
tmpl, err := template.New("greeting").Parse(message)
if err != nil {
	panic(err)
}
data := struct {
	Greeting string
	Number   *big.Int
}{
	Greeting: "World",
	Number:   value,
}
if err := tmpl.Execute(os.Stdout, data); err != nil {
	panic(err)
}

